        && input.is_contiguous() && output.is_contiguous()
        && input.sizes() == output.sizes(),
        "matching contiguous batched square matrices required"
    );
    const int n = static_cast<int>(input.size(1));
    const int batch = static_cast<int>(input.size(0));
    TORCH_CHECK((n & 3) == 0, "matrix width must be float4 aligned");
    const int rows = batch * n;
    const int row_groups = (rows + 7) / 8;
    const int blocks = row_groups < 2048 ? row_groups : 2048;
    batch_lower_copy_kernel<<<
        blocks, 256, 0,
