         linear_row += static_cast<int>(gridDim.x) * 16) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int diagonal_start = row & ~255;
        const int diagonal_row = row - diagonal_start;
        const int full_vectors = diagonal_row / 4;
        float4* output_vectors = reinterpret_cast<float4*>(
